package main

import (
	crand "crypto/rand"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/exec"
	"strconv"
	"time"

	"github.com/go-sql-driver/mysql"
	"github.com/jmoiron/sqlx"
)

var db *sqlx.DB

func main() {
	host := getenv("ISUCON_DB_HOST", "127.0.0.1")
	port := getenv("ISUCON_DB_PORT", "3306")
	user := getenv("ISUCON_DB_USER", "isucon")
	password := getenv("ISUCON_DB_PASSWORD", "isucon")
	dbname := getenv("ISUCON_DB_NAME", "isuride")

	dbConfig := mysql.NewConfig()
	dbConfig.User = user
	dbConfig.Passwd = password
	dbConfig.Addr = net.JoinHostPort(host, port)
	dbConfig.Net = "tcp"
	dbConfig.DBName = dbname
	dbConfig.ParseTime = true
	dbConfig.InterpolateParams = true

	var err error
	for i := 0; i < 120; i++ {
		db, err = sqlx.Connect("mysql", dbConfig.FormatDSN())
		if err == nil {
			break
		}
		log.Printf("db connect failed: %v", err)
		time.Sleep(time.Second)
	}
	if err != nil {
		panic(err)
	}
	db.SetMaxOpenConns(20)
	db.SetMaxIdleConns(20)

	for i := 0; i < 60; i++ {
		if err = loadAll(); err == nil {
			break
		}
		log.Printf("load failed: %v", err)
		time.Sleep(time.Second)
	}
	if err != nil {
		panic(err)
	}

	go dbWriter()
	go matcherLoop()

	mux := http.NewServeMux()
	mux.HandleFunc("POST /api/initialize", postInitialize)

	mux.HandleFunc("POST /api/app/users", appPostUsers)
	mux.HandleFunc("POST /api/app/payment-methods", appAuth(appPostPaymentMethods))
	mux.HandleFunc("GET /api/app/rides", appAuth(appGetRides))
	mux.HandleFunc("POST /api/app/rides", appAuth(appPostRides))
	mux.HandleFunc("POST /api/app/rides/estimated-fare", appAuth(appPostRidesEstimatedFare))
	mux.HandleFunc("POST /api/app/rides/{ride_id}/evaluation", appAuth(appPostRideEvaluation))
	mux.HandleFunc("GET /api/app/notification", appAuth(appGetNotification))
	mux.HandleFunc("GET /api/app/nearby-chairs", appAuth(appGetNearbyChairs))

