type ctxHandler[T any] func(w http.ResponseWriter, r *http.Request, v T)

func appAuth(h ctxHandler[*User]) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		c, err := r.Cookie("app_session")
		if err != nil || c.Value == "" {
			writeError(w, http.StatusUnauthorized, errors.New("app_session cookie is required"))
			return
		}
		mu.Lock()
		u := usersByToken[c.Value]
		mu.Unlock()
		if u == nil {
			writeError(w, http.StatusUnauthorized, errors.New("invalid access token"))
			return
		}
		h(w, r, u)
	}
}

func ownerAuth(h ctxHandler[*Owner]) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		c, err := r.Cookie("owner_session")
		if err != nil || c.Value == "" {
			writeError(w, http.StatusUnauthorized, errors.New("owner_session cookie is required"))
			return
		}
		mu.Lock()
		o := ownersByToken[c.Value]
		mu.Unlock()
		if o == nil {
			writeError(w, http.StatusUnauthorized, errors.New("invalid access token"))
			return
		}
		h(w, r, o)
	}
}

func chairAuth(h ctxHandler[*Chair]) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		c, err := r.Cookie("chair_session")
		if err != nil || c.Value == "" {
			writeError(w, http.StatusUnauthorized, errors.New("chair_session cookie is required"))
			return
		}
		mu.Lock()
		ch := chairsByToken[c.Value]
		mu.Unlock()
		if ch == nil {
			writeError(w, http.StatusUnauthorized, errors.New("invalid access token"))
			return
		}
		h(w, r, ch)
	}
}

// ======================= app =======================

type appPostUsersRequest struct {
	Username       string  `json:"username"`
	FirstName      string  `json:"firstname"`
	LastName       string  `json:"lastname"`
	DateOfBirth    string  `json:"date_of_birth"`
	InvitationCode *string `json:"invitation_code"`
}

type appPostUsersResponse struct {
	ID             string `json:"id"`
	InvitationCode string `json:"invitation_code"`
}

func appPostUsers(w http.ResponseWriter, r *http.Request) {
	req := &appPostUsersRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if req.Username == "" || req.FirstName == "" || req.LastName == "" || req.DateOfBirth == "" {
		writeError(w, http.StatusBadRequest, errors.New("required fields(username, firstname, lastname, date_of_birth) are empty"))
		return
	}
	userID := ulid.Make().String()
	accessToken := secureRandomStr(32)
	invitationCode := secureRandomStr(15)
	now := nowMicro()

	mu.Lock()
	if usernames[req.Username] {
		mu.Unlock()
		writeError(w, http.StatusInternalServerError, errors.New("duplicate username"))
		return
	}
	var inviter *User
	inv := ""
	if req.InvitationCode != nil && *req.InvitationCode != "" {
		inv = *req.InvitationCode
		if invCount[inv] >= 3 {
			mu.Unlock()
			writeError(w, http.StatusBadRequest, errors.New("この招待コードは使用できません。"))
			return
		}
		inviter = usersByInvCode[inv]
		if inviter == nil {
			mu.Unlock()
			writeError(w, http.StatusBadRequest, errors.New("この招待コードは使用できません。"))
			return
		}
	}
	u := &User{
		ID: userID, Username: req.Username, Firstname: req.FirstName, Lastname: req.LastName,
		DateOfBirth: req.DateOfBirth, AccessToken: accessToken, InvitationCode: invitationCode,
		CreatedAt: now, notif: newNotifier(),
	}
	usersByID[userID] = u
	usersByToken[accessToken] = u
	usersByInvCode[invitationCode] = u
	usernames[req.Username] = true
	enqueue("INSERT INTO users (id, username, firstname, lastname, date_of_birth, access_token, invitation_code, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
		userID, req.Username, req.FirstName, req.LastName, req.DateOfBirth, accessToken, invitationCode, now, now)
	u.Coupons = append(u.Coupons, &Coupon{Code: "CP_NEW2024", Discount: 3000, CreatedAt: now})
	enqueue("INSERT INTO coupons (user_id, code, discount, created_at) VALUES (?, ?, ?, ?)", userID, "CP_NEW2024", 3000, now)
	if inviter != nil {
		invCount[inv]++
		u.Coupons = append(u.Coupons, &Coupon{Code: "INV_" + inv, Discount: 1500, CreatedAt: now})
		enqueue("INSERT INTO coupons (user_id, code, discount, created_at) VALUES (?, ?, ?, ?)", userID, "INV_"+inv, 1500, now)
		code := "RWD_" + inv + "_" + strconv.FormatInt(now.UnixMilli(), 10)
		inviter.Coupons = append(inviter.Coupons, &Coupon{Code: code, Discount: 1000, CreatedAt: now})
		enqueue("INSERT INTO coupons (user_id, code, discount, created_at) VALUES (?, ?, ?, ?)", inviter.ID, code, 1000, now)
	}
	mu.Unlock()

	http.SetCookie(w, &http.Cookie{Path: "/", Name: "app_session", Value: accessToken})
	writeJSON(w, http.StatusCreated, &appPostUsersResponse{ID: userID, InvitationCode: invitationCode})
}

type appPostPaymentMethodsRequest struct {
	Token string `json:"token"`
}

func appPostPaymentMethods(w http.ResponseWriter, r *http.Request, user *User) {
	req := &appPostPaymentMethodsRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if req.Token == "" {
		writeError(w, http.StatusBadRequest, errors.New("token is required but was empty"))
		return
	}
	now := nowMicro()
	mu.Lock()
	user.PaymentToken = req.Token
	enqueue("INSERT INTO payment_tokens (user_id, token, created_at) VALUES (?, ?, ?) ON DUPLICATE KEY UPDATE token = VALUES(token)", user.ID, req.Token, now)
	mu.Unlock()
	w.WriteHeader(http.StatusNoContent)
}

type getAppRidesResponse struct {
	Rides []getAppRidesResponseItem `json:"rides"`
}

type getAppRidesResponseItem struct {
	ID                    string                       `json:"id"`
	PickupCoordinate      Coordinate                   `json:"pickup_coordinate"`
	DestinationCoordinate Coordinate                   `json:"destination_coordinate"`
	Chair                 getAppRidesResponseItemChair `json:"chair"`
	Fare                  int                          `json:"fare"`
	Evaluation            int                          `json:"evaluation"`
	RequestedAt           int64                        `json:"requested_at"`
	CompletedAt           int64                        `json:"completed_at"`
}

type getAppRidesResponseItemChair struct {
	ID    string `json:"id"`
	Owner string `json:"owner"`
	Name  string `json:"name"`
	Model string `json:"model"`
}

func appGetRides(w http.ResponseWriter, r *http.Request, user *User) {
	items := []getAppRidesResponseItem{}
	mu.Lock()
	for i := len(user.Rides) - 1; i >= 0; i-- {
		ride := user.Rides[i]
		if ride.Status != "COMPLETED" {
			continue
		}
		item := getAppRidesResponseItem{
			ID:                    ride.ID,
			PickupCoordinate:      Coordinate{ride.PickupLat, ride.PickupLon},
			DestinationCoordinate: Coordinate{ride.DestLat, ride.DestLon},
			Fare:                  ride.Fare(),
			Evaluation:            ride.Evaluation,
			RequestedAt:           ride.CreatedAt.UnixMilli(),
			CompletedAt:           ride.UpdatedAt.UnixMilli(),
		}
		if c := chairsByID[ride.ChairID]; c != nil {
			item.Chair.ID = c.ID
			item.Chair.Name = c.Name
			item.Chair.Model = c.Model
			if o := ownersByID[c.OwnerID]; o != nil {
				item.Chair.Owner = o.Name
			}
		}
		items = append(items, item)
	}
	mu.Unlock()
	writeJSON(w, http.StatusOK, &getAppRidesResponse{Rides: items})
}

type appPostRidesRequest struct {
	PickupCoordinate      *Coordinate `json:"pickup_coordinate"`
	DestinationCoordinate *Coordinate `json:"destination_coordinate"`
}

type appPostRidesResponse struct {
	RideID string `json:"ride_id"`
	Fare   int    `json:"fare"`
}

func appPostRides(w http.ResponseWriter, r *http.Request, user *User) {
	req := &appPostRidesRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if req.PickupCoordinate == nil || req.DestinationCoordinate == nil {
		writeError(w, http.StatusBadRequest, errors.New("required fields(pickup_coordinate, destination_coordinate) are empty"))
		return
	}
	rideID := ulid.Make().String()
	statusID := ulid.Make().String()
	now := nowMicro()

	mu.Lock()
	for _, rd := range user.Rides {
		if rd.Status != "COMPLETED" {
			mu.Unlock()
			writeError(w, http.StatusConflict, errors.New("ride already exists"))
			return
		}
	}
	ride := &Ride{
		ID: rideID, UserID: user.ID,
		PickupLat: req.PickupCoordinate.Latitude, PickupLon: req.PickupCoordinate.Longitude,
		DestLat: req.DestinationCoordinate.Latitude, DestLon: req.DestinationCoordinate.Longitude,
		Status: "MATCHING", CreatedAt: now, UpdatedAt: now,
	}
	var coupon *Coupon
	if len(user.Rides) == 0 {
		coupon = user.nextCoupon()
	} else {
		for _, c := range user.Coupons {
			if c.UsedBy != "" {
				continue
			}
			if coupon == nil || c.CreatedAt.Before(coupon.CreatedAt) {
				coupon = c
			}
		}
	}
	user.Rides = append(user.Rides, ride)
	ridesByID[rideID] = ride
	enqueue("INSERT INTO rides (id, user_id, pickup_latitude, pickup_longitude, destination_latitude, destination_longitude, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
		rideID, user.ID, ride.PickupLat, ride.PickupLon, ride.DestLat, ride.DestLon, now, now)
	enqueue("INSERT INTO ride_statuses (id, ride_id, status, created_at) VALUES (?, ?, ?, ?)", statusID, rideID, "MATCHING", now)
	if coupon != nil {
		coupon.UsedBy = rideID
		ride.Discount = coupon.Discount
		enqueue("UPDATE coupons SET used_by = ? WHERE user_id = ? AND code = ?", rideID, user.ID, coupon.Code)
	}
	fare := ride.Fare()
	notifyUser(ride)
	waitingRides = append(waitingRides, ride)
	mu.Unlock()

	writeJSON(w, http.StatusAccepted, &appPostRidesResponse{RideID: rideID, Fare: fare})
}

type appPostRidesEstimatedFareResponse struct {
	Fare     int `json:"fare"`
	Discount int `json:"discount"`
}

func appPostRidesEstimatedFare(w http.ResponseWriter, r *http.Request, user *User) {
	req := &appPostRidesRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if req.PickupCoordinate == nil || req.DestinationCoordinate == nil {
		writeError(w, http.StatusBadRequest, errors.New("required fields(pickup_coordinate, destination_coordinate) are empty"))
		return
	}
	discount := 0
	mu.Lock()
	if c := user.nextCoupon(); c != nil {
		discount = c.Discount
	}
	mu.Unlock()
	full := calculateFare(req.PickupCoordinate.Latitude, req.PickupCoordinate.Longitude, req.DestinationCoordinate.Latitude, req.DestinationCoordinate.Longitude)
	metered := full - initialFare
	discounted := initialFare + max(metered-discount, 0)
	writeJSON(w, http.StatusOK, &appPostRidesEstimatedFareResponse{Fare: discounted, Discount: full - discounted})
}

type appPostRideEvaluationRequest struct {
	Evaluation int `json:"evaluation"`
}

type appPostRideEvaluationResponse struct {
	CompletedAt int64 `json:"completed_at"`
}

func appPostRideEvaluation(w http.ResponseWriter, r *http.Request, user *User) {
	rideID := r.PathValue("ride_id")
	req := &appPostRideEvaluationRequest{}
	if err := bindJSON(r, req); err != nil {
		writeError(w, http.StatusBadRequest, err)
		return
	}
	if req.Evaluation < 1 || req.Evaluation > 5 {
		writeError(w, http.StatusBadRequest, errors.New("evaluation must be between 1 and 5"))
		return
	}

	mu.Lock()
	ride := ridesByID[rideID]
	if ride == nil {
		mu.Unlock()
		writeError(w, http.StatusNotFound, errors.New("ride not found"))
		return
	}
	if ride.Status != "ARRIVED" || ride.evaluating {
		mu.Unlock()
		writeError(w, http.StatusBadRequest, errors.New("not arrived yet"))
		return
	}
	owner := usersByID[ride.UserID]
	token := ""
	if owner != nil {
		token = owner.PaymentToken
	}
	if token == "" {
		mu.Unlock()
		writeError(w, http.StatusBadRequest, errors.New("payment token not registered"))
		return
	}
	fare := ride.Fare()
	ride.evaluating = true
	url := paymentGatewayURL
	mu.Unlock()

	if err := requestPayment(r.Context(), url, token, fare, ride.ID); err != nil {
		mu.Lock()
		ride.evaluating = false
		mu.Unlock()
		writeError(w, http.StatusBadGateway, err)
		return
	}

	now := nowMicro()
	mu.Lock()
	ride.evaluating = false
	ride.Evaluation = req.Evaluation
	ride.Status = "COMPLETED"
	ride.UpdatedAt = now
	if c := chairsByID[ride.ChairID]; c != nil {
		c.RideCount++
		c.EvalSum += req.Evaluation
		c.Completed = append(c.Completed, ride)
	}
	enqueue("UPDATE rides SET evaluation = ?, updated_at = ? WHERE id = ?", req.Evaluation, now, ride.ID)
	enqueue("INSERT INTO ride_statuses (id, ride_id, status, created_at) VALUES (?, ?, ?, ?)", ulid.Make().String(), ride.ID, "COMPLETED", now)
	notifyUser(ride)
	notifyChair(ride)
	mu.Unlock()

	writeJSON(w, http.StatusOK, &appPostRideEvaluationResponse{CompletedAt: now.UnixMilli()})
}

func appGetNotification(w http.ResponseWriter, r *http.Request, user *User) {
	serveSSE(w, r, user.notif)
}

type appGetNearbyChairsResponse struct {
	Chairs      []appGetNearbyChairsResponseChair `json:"chairs"`
	RetrievedAt int64                             `json:"retrieved_at"`
}

type appGetNearbyChairsResponseChair struct {
