	Name              string     `json:"name"`
	Model             string     `json:"model"`
	CurrentCoordinate Coordinate `json:"current_coordinate"`
}

func appGetNearbyChairs(w http.ResponseWriter, r *http.Request, user *User) {
	q := r.URL.Query()
	latStr := q.Get("latitude")
	lonStr := q.Get("longitude")
	if latStr == "" || lonStr == "" {
		writeError(w, http.StatusBadRequest, errors.New("latitude or longitude is empty"))
		return
	}
	lat, err := strconv.Atoi(latStr)
	if err != nil {
		writeError(w, http.StatusBadRequest, errors.New("latitude is invalid"))
		return
	}
	lon, err := strconv.Atoi(lonStr)
	if err != nil {
		writeError(w, http.StatusBadRequest, errors.New("longitude is invalid"))
		return
	}
	distance, err := atoiDefault(q.Get("distance"), 50)
	if err != nil {
		writeError(w, http.StatusBadRequest, errors.New("distance is invalid"))
		return
	}
	res := []appGetNearbyChairsResponseChair{}
	mu.Lock()
	for _, c := range chairList {
		if !c.IsActive || !c.HasLoc || !c.isFree() {
			continue
		}
		if calculateDistance(lat, lon, c.Lat, c.Lon) <= distance {
			res = append(res, appGetNearbyChairsResponseChair{
				ID: c.ID, Name: c.Name, Model: c.Model,
				CurrentCoordinate: Coordinate{c.Lat, c.Lon},
			})
		}
	}
	mu.Unlock()
	writeJSON(w, http.StatusOK, &appGetNearbyChairsResponse{Chairs: res, RetrievedAt: time.Now().UnixMilli()})
}

