func chairPostChairs(w http.ResponseWriter, r *http.Request) {
	req := &chairPostChairsRequest{}
	if err := bindJSON(r, req); err != nil {
		w.WriteHeader(http.StatusBadRequest)
		return
	}
	if req.Name == "" || req.Model == "" || req.ChairRegisterToken == "" {
		writeError(w, http.StatusBadRequest, errors.New("some of required fields(name, model, chair_register_token) are empty"))
		return
	}
	chairID := ulid.Make().String()
	accessToken := secureRandomStr(32)
	now := nowMicro()

	mu.Lock()
	owner := ownersByRegToken[req.ChairRegisterToken]
	if owner == nil {
		mu.Unlock()
		writeError(w, http.StatusUnauthorized, errors.New("invalid chair_register_token"))
		return
	}
	speed := modelSpeed[req.Model]
	if speed == 0 {
		speed = 1
	}
	c := &Chair{
		ID: chairID, OwnerID: owner.ID, Name: req.Name, Model: req.Model, Speed: speed,
		AccessToken: accessToken, CreatedAt: now, notif: newNotifier(),
	}
	chairsByID[chairID] = c
	chairsByToken[accessToken] = c
	chairList = append(chairList, c)
	owner.Chairs = append(owner.Chairs, c)
	enqueue("INSERT INTO chairs (id, owner_id, name, model, is_active, access_token, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
		chairID, owner.ID, req.Name, req.Model, false, accessToken, now, now)
	mu.Unlock()

	http.SetCookie(w, &http.Cookie{Path: "/", Name: "chair_session", Value: accessToken})
	writeJSON(w, http.StatusCreated, &chairPostChairsResponse{ID: chairID, OwnerID: owner.ID})
