cd /work/webapp/go && python3 - <<'EOF'
p='handlers.go'; s=open(p).read()
s=s.replace("""	if usernames[req.Username] {
		mu.Unlock()
		writeError(w, http.StatusInternalServerError, errors.New("duplicate username"))
		return
	}
""","")
open(p,'w').write(s)
p='main.go'; s=open(p).read()
s=s.replace("""	srv := &http.Server{Addr: ":8080", Handler: mux}""","""	go statsLoop()
	srv := &http.Server{Addr: ":8080", Handler: countMW(mux)}""")
s+='''
var (
	statMu sync.Mutex
	stats  = map[string]int{}
)

func countMW(h http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		h.ServeHTTP(w, r)
		statMu.Lock()
		stats[r.Pattern]++
		statMu.Unlock()
	})
}

func statsLoop() {
	for range time.Tick(10 * time.Second) {
		statMu.Lock()
		if len(stats) == 0 {
			statMu.Unlock()
			continue
		}
		s := stats
		stats = map[string]int{}
		statMu.Unlock()
		keys := make([]string, 0, len(s))
		for k := range s {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		var b strings.Builder
		for _, k := range keys {
			fmt.Fprintf(&b, "%s=%d ", k, s[k])
		}
		mu.Lock()
		nw := len(waitingRides)
		nc := len(chairList)
		mu.Unlock()
		log.Printf("stats waiting=%d chairs=%d writeq=%d %s", nw, nc, len(writeCh), b.String())
	}
}
'''
s=s.replace('"strconv"\n','"sort"\n\t"strconv"\n\t"strings"\n\t"sync"\n')
open(p,'w').write(s)
EOF
go build -o isuride . && echo ok

cat > /tmp/nginx.conf <<'EOF'
user www-data;
worker_processes auto;
worker_cpu_affinity auto;
worker_rlimit_nofile 100000;
pid /run/nginx.pid;
error_log /var/log/nginx/error.log;
include /etc/nginx/modules-enabled/*.conf;

events {
	worker_connections 16384;
	multi_accept on;
	use epoll;
}

http {
	sendfile on;
	tcp_nopush on;
	tcp_nodelay on;
	types_hash_max_size 2048;
	server_tokens off;
	keepalive_timeout 120s;
	keepalive_requests 1000000;

	include /etc/nginx/mime.types;
	default_type application/octet-stream;

	ssl_protocols TLSv1.2 TLSv1.3;
	ssl_prefer_server_ciphers on;

	access_log off;
	gzip off;

	include /etc/nginx/conf.d/*.conf;
	include /etc/nginx/sites-enabled/*;
}
EOF
